def tick_status(world: World, actor: Actor):
    if not actor.alive:
        return
    for name in list(actor.statuses):
        if name == "poison":
            # Poison bypasses shield and never reduces HP below 1
            if actor.hp > 1:
                actor.hp -= 1
                world.events.append(Event("poison_tick", actor.actor_id, amount=1))
                if not actor.alive:
                    world.events.append(Event("death", actor.actor_id))
        actor.statuses[name] -= 1
        if actor.statuses[name] <= 0:
            del actor.statuses[name]

